public static partial class EnglishQuotes
{
    public static class WilliamWordsworth
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I travelled among unknown men, In lands beyond the sea; Nor, England! did I know till then What love I bore to thee.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Sweet childish days, that were as long As twenty days are now.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "My heart leaps up when I behold A rainbow in the sky: So was it when my life began; So is it now I am a man; So be it when I shall grow old, Or let me die!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The Child is father of the Man; And I could wish my days to be Bound each to each by natural piety.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Earth has not anything to show more fair: Dull would he be of soul who could pass by A sight so touching in its majesty: This City now doth, like a garment, wear The beauty of the morning; silent, bare, Ships, towers, domes, theatres and temples lie Open unto the fields and to the sky; All bright and glittering in the smokeless air.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Ne'er saw I, never felt, a calm so deep! The river glideth at his own sweet will: Dear God! the very houses seem asleep; And all that mighty heart is lying still!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Rapine, avarice, expense This is idolatry; and these we adore: Plain living and high thinking are no more: The homely beauty of the good old cause Is gone; our peace, our fearful innocence, And pure religion breathing household laws.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Pleasures newly found are sweet When they lie about our feet.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Every gift of noble origin Is breathed upon by Hope's perpetual breath.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "There is a Yew-tree, pride of Lorton Vale, Which to this day stands single, in the midst Of its own darkness, as it stood of yore.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "This solitary Tree! A living thing Produced too slowly ever to decay; Of form and aspect too magnificent To be destroyed.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Bright flower! whose home is everywhere Bold in maternal nature's care And all the long year through the heir Of joy or sorrow,", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "O Blithe newcomer! I have heard, I hear thee and rejoice. O Cuckoo! shall I call thee Bird, Or but a wandering Voice?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "No bird, but an invisible thing, A voice, a mystery.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thou unassuming Common-place Of Nature, with that homely face, And yet with something of a grace, Which Love makes for thee!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Oft on the dappled turf at ease I sit, and play with similes, Loose types of things through all degrees.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The light that never was, on sea or land, The consecration, and the poet's dream.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Dear Child of Nature, let them rail!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thou, while thy babes around thee cling, Shalt show us how divine a thing A Woman may be made.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But an old age serene and bright, And lovely as a Lapland night, Shall lead thee to thy grave.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "She hath smiles to earth unknown— Smiles that with motion of their own Do spread, and sink, and rise.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Like—but oh, how different!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "In truth the prison, unto which we doom Ourselves, no prison is.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The world is too much with us; late and soon, Getting and spending, we lay waste our powers: Little we see in Nature that is ours; We have given our hearts away, a sordid boon!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Great God! I'd rather be A Pagan suckled in a creed outworn; So might I, standing on this pleasant lea, Have glimpses that would make me less forlorn; Have sight of Proteus rising from the sea; Or hear old Triton blow his wreathèd horn.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Where lies the Land to which yon Ship must go? Fresh as a lark mounting at break of day, Festively she puts forth in trim array.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Come, blessed barrier between day and day, Dear mother of fresh thoughts and joyous health!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Dreams, books, are each a world; and books, we know, Are a substantial world, both pure and good: Round these, with tendrils strong as flesh and blood, Our pastime and our happiness will grow.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Every great and original writer, in proportion as he is great and original, must himself create the taste by which he is to be relished.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "It is a beauteous evening, calm and free, The holy time is quiet as a Nun Breathless with adoration; the broad sun Is sinking down in its tranquillity; The gentleness of heaven broods o'er the Sea.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thou liest in Abraham's bosom all the year; And worship'st at the Temple's inner shrine, God being with thee when we know it not.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Once did She hold the gorgeous east in fee; And was the safeguard of the west: the worth Of Venice did not fall below her birth, Venice, the eldest Child of Liberty.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Men are we, and must grieve when even the Shade Of that which once was great, is passed away.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thou has left behind Powers that will work for thee,—air, earth, and skies! There 's not a breathing of the common wind That will forget thee; thou hast great allies; Thy friends are exultations, agonies, And love, and man's unconquerable mind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Milton! thou should'st be living at this hour: England hath need of thee: she is a fen Of stagnant waters.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thy soul was like a Star, and dwelt apart: Thou hadst a voice whose sound was like the sea: Pure as the naked heavens, majestic, free, So didst thou travel on life's common way, In cheerful godliness.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "We must be free or die, who speak the tongue That Shakespeare spake; the faith and morals hold Which Milton held.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "He sang of love, with quiet blending, Slow to begin, and never ending; Of serious faith, and inward glee; That was the song,—the song for me!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Two Voices are there; one is of the sea, One of the mountains; each a mighty Voice.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Love had he found in huts where poor men lie; His daily teachers had been woods and rills, The silence that is in the starry sky, The sleep that is among the lonely hills.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Action is transitory—a step, a blow— The motion of a muscle—this way or that— 'Tis done; and in the after-vacancy We wonder at ourselves like men betrayed.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A few strong instincts and a few plain rules, Among the herdsmen of the Alps, have wrought More for mankind at this unhappy day Then all the pride of intellect and thought?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Fill your paper with the breathings of your heart.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A cheerful life is what the Muses love, A soaring spirit is their prime delight.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But shapes that come not at an earthly call, Will not depart when mortal voices bid.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Surprised by joy—impatient as the Wind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And beauty, for confiding youth, Those shocks of passion can prepare That kill the bloom before its time; And blanch, without the owner's crime, The most resplendent hair.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "What is pride? A whizzing rocket That would emulate a star.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Enough, if something from our hands have power To live, and act, and serve the future hour.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Through love, through hope, and faith's transcendent dower, We feel that we are greater than we know.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The flower of sweetest smell is shy and lowly.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Lives there a man whose sole delights Are trivial pomp and city noise, Hardening a heart that loathes or slights What every natural heart enjoys?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A soul so pitiably forlorn, If such do on this earth abide, May season apathy with scorn, May turn indifference to pride; And still be not unblest—compared With him who grovels, self-debarred From all that lies within the scope Of holy faith and christian hope; Or, shipwrecked, kindles on the coast False fires, that others may be lost.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But hushed be every thought that springs From out the bitterness of things.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "True beauty dwells in deep retreats, Whose veil is unremoved Till heart with heart in concord beats, And the lover is beloved.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Type of the wise who soar, but never roam; True to the kindred points of Heaven and Home!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Scorn not the Sonnet; Critic, you have frowned, Mindless of its just honours; with this key Shakespeare unlocked his heart", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Ocean is a mighty harmonist.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "These feeble and fastidious times.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Myriads of daisies have shone forth in flower Near the lark's nest, and in their natural hour Have passed away; less happy than the one That by the unwilling ploughshare died to prove The tender charm of poetry and love.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Small service is true service while it lasts. Of humblest friends, bright creature! scorn not one: The daisy, by the shadow that it casts, Protects the lingering dewdrop from the sun.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "One solace yet remains for us who came Into this world in days when story lacked Severe research, that in our hearts we know How, for exciting youth's heroic flame, Assent is power, belief the soul of fact.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "How does the Meadow-flower its bloom unfold? Because the lovely little flower is free Down to its root, and, in that freedom, bold.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Minds that have nothing to confer Find little to perceive.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "There's something in a flying horse, There's something in a huge balloon; But through the clouds I'll never float Until I have a little Boat, Shaped like the crescent-moon.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The common growth of Mother Earth Suffices me,—her tears, her mirth, Her humblest mirth and tears.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A primrose by a river's brim A yellow primrose was to him, And it was nothing more.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The soft blue sky did never melt Into his heart; he never felt The witchery of the soft blue sky!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "On a fair prospect some have looked, And felt, as I have heard them say, As if the moving time had been A thing as steadfast as the scene On which they gazed themselves away.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "As if the man had fixed his face, In many a solitary place, Against the wind and open sky!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The Poet writes under one restriction only, namely, the necessity of giving immediate pleasure ... Nor let this necessity ... be considered as a degradation of the Poet’s art. It is far otherwise. It is an acknowledgment of the beauty of the universe, an acknowledgment the more sincere because not formal, but indirect; it is a task light and easy to him who looks at the world in the spirit of love; further, it is a homage paid to the native and naked dignity of Humanity, to the grand elementary principle of pleasure, by which he knows and feels and lives and moves … Poetry is the breath and finer spirit of all knowledge; it is the impassioned expression which is in the countenance of all Science ... In spite of difference of soil and climate, of language and manners, of laws and customs, — in spite of things silently gone out of mind, and things violently destroyed, the Poet binds together by passion and knowledge the vast empire of human society, as it is spread over the whole earth, and over all time ... Poetry is the first and last of all knowledge — it is as immortal as the heart of man.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The human mind is capable of excitement without the application of gross and violent stimulants; and he must have a very faint perception of its beauty and dignity who does not know this.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A multitude of causes unknown to former times are now acting with a combined force to blunt the discriminating powers of the mind, and unfitting it for all voluntary exertion to reduce it to a state of almost savage torpor.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "What is a Poet?...He is a man speaking to men: a man, it is true, endowed with more lively sensibility, more enthusiasm and tenderness, who has a greater knowledge of human nature, and a more comprehensive soul, than are supposed to be common among mankind; a man pleased with his own passions and volitions, and who rejoices more than other men in the spirit of life that is in him; delighting to contemplate similar volitions and passions as manifested in the goings-on of the Universe, and habitually impelled to create them where he does not find them.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I have said that poetry is the spontaneous overflow of powerful feelings: it takes its origin from emotion recollected in tranquility.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "All men feel something of an honorable bigotry for the objects which have long continued to please them.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "From the sweet thoughts of home And from all hope I was forever hurled. For me—farthest from earthly port to roam Was best, could I but shun the spot where man might come.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And homeless near a thousand homes I stood, And near a thousand tables pined and wanted food.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A simple child, That lightly draws its breath, And feels its life in every limb, What should it know of death?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "In that sweet mood when pleasant thoughts Bring sad thoughts to the mind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Have I not reason to lament What man has made of man?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The eye—it cannot choose but see; we cannot bid the ear be still; our bodies feel, where'er they be, Against or with our will.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Nor less I deem that there are Powers Which of themselves our minds impress; That we can feed this mind of ours In a wise passiveness.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Come forth into the light of things, Let Nature be your teacher.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "One impulse from a vernal wood May teach you more of man, Of moral evil and of good, Than all the sages can.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "O Reader! had you in your mind Such stores as silent thought can bring, O gentle Reader! you would find A tale in everything.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I've heard of hearts unkind, kind deeds With coldness still returning; Alas! the gratitude of men Hath oftener left me mourning.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "What fond and wayward thoughts will slide Into a lover's head! \"O mercy!\" to myself I cried, \"If Lucy should be dead!\"", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "She dwelt among the untrodden ways Beside the springs of Dove, A maid whom there were none to praise And very few to love:", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "She lived unknown, and few could know When Lucy ceased to be; But she is in her grave, and, oh, The difference to me!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Three years she grew in sun and shower, Then Nature said, \"A lovelier flower On earth was never sown; This Child I to myself will take; She shall be mine, and I will make A Lady of my own.\"", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A slumber did my spirit seal; I had no human fears: She seemed a thing that could not feel The touch of earthly years.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "No motion has she now, no force; She neither hears nor sees; Rolled round in earth's diurnal course, With rocks, and stones, and trees.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The sweetest thing that ever grew Beside a human door!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And sings a solitary song That whistles in the wind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A youth to whom was given So much of earth—so much of heaven, And such impetuous blood.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "My eyes are dim with childish tears, My heart is idly stirred, For the same sound is in my ears Which in those days I heard.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thus fares it still in our decay: And yet the wiser mind Mourns less for what age takes away Than what it leaves behind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Something between a hindrance and a help.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Drink, pretty creature, drink!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "May no rude hand deface it, And its forlorn Hic jacet!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Lady of the Mere, Sole-sitting by the shores of old romance.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Who he was That piled these stones, and with the mossy sod First covered, and here taught this aged Tree With its dark arms to form a circling bower, I well remember. He was one who owned No common soul. In youth by science nursed. And led by nature into a wild scene Of lofty hopes, he to the world went forth A favoured Being, knowing no desire Which genius did not hallow; 'gainst the taint Of dissolute tongues, and jealousy, and hate, And scorn,—against all enemies prepared, All but neglect. The world, for so it thought, Owed him no service; wherefore he at once With indignation turned himself away, And with the food of pride sustained his soul In solitude.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A morbid pleasure nourished, tracing here An emblem of his own unfruitful life: And, lifting up his head, he then would gaze On the more distant scene,—how lovely 'tis Thou seest,—and he would gaze till it became Far lovelier, and his heart could not sustain The beauty, still more beauteous! Nor, that time, When nature had subdued him to herself, Would he forget those Beings to whose minds, Warm from the labours of benevolence, The world and human life appeared a scene Of kindred loveliness: then he would sigh, Inly disturbed, to think that others felt What he must never feel: and so, lost Man! On visionary views would fancy feed, Till his eye streamed with tears. In this deep vale He died,—this seat his only monument.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "If Thou be one whose heart the holy forms Of young imagination have kept pure Stranger! henceforth be warned; and know that pride, Howe'er disguised in its own majesty, Is littleness; that he who feels contempt For any living thing, hath faculties Which he has never used; that thought with him Is in its infancy. The man whose eye Is ever on himself doth look on one, The least of Nature's works, one who might move The wise man to that scorn which wisdom holds Unlawful, ever. O be wiser, thou ! Instructed that true knowledge leads to love; True dignity abides with him alone Who, in the silent hour of inward thought, Can still suspect, and still revere himself, In lowliness of heart.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Oh, be wise, Thou! Instructed that true knowledge leads to love.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Five years have passed; five summers, with the length Of five long winters! and again I hear These waters, rolling from their mountain-springs With a sweet inland murmur.—Once again Do I behold these steep and lofty cliffs, Which on a wild secluded scene impress Thoughts of more deep seclusion; and connect The landscape with the quiet of the sky.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "These beauteous forms, Through a long absence, have not been to me As is a landscape to a blind man's eye: But oft, in lonely rooms, and 'mid the din Of towns and cities, I have owed to them, In hours of weariness, sensations sweet, Felt in the blood, and felt along the heart; And passing even into my purer mind, With tranquil restoration:—feelings too Of unremembered pleasure: such, perhaps, As have no slight or trivial influence On that best portion of a good man's life, His little, nameless, unremembered acts Of kindness and of love.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "That serene and blessed mood, In which the affections gently lead us on,— Until, the breath of this corporeal frame And even the motion of our human blood Almost suspended, we are laid asleep In body, and become a living soul: While with an eye made quiet by the power Of harmony, and the deep power of joy, We see into the life of things.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "O sylvan Wye! thou wanderer thro' the woods, How often has my spirit turned to thee!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The picture of the mind revives again: While here I stand, not only with the sense Of present pleasure, but with pleasing thoughts That in this moment there is life and food For future years.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "For nature then (The coarser pleasures of my boyish days, And their glad animal movements all gone by) To me was all in all.—I cannot paint What then I was.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The sounding cataract Haunted me like a passion: the tall rock, The mountain, and the deep and gloomy wood, Their colours and their forms, were then to me An appetite; a feeling and a love, That had no need of a remoter charm, By thought supplied, nor any interest Unborrowed from the eye.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "That time is past, And all its aching joys are now no more, And all its dizzy raptures. Not for this Faint I, nor mourn nor murmur, other gifts Have followed; for such loss, I would believe, Abundant recompence.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "For I have learned To look on nature, not as in the hour Of thoughtless youth; but hearing oftentimes The still, sad music of humanity, Nor harsh nor grating, though of ample power To chasten and subdue.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A sense sublime Of something far more deeply interfused, Whose dwelling is the light of setting suns, And the round ocean and the living air, And the blue sky, and in the mind of man; A motion and a spirit, that impels All thinking things, all objects of all thought, And rolls through all things.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Therefore am I still A lover of the meadows and the woods, And mountains; and of all that we behold From this green earth; of all the mighty world Of eye, and ear,—both what they half create, And what perceive; well pleased to recognise In nature and the language of the sense, The anchor of my purest thoughts, the nurse, The guide, the guardian of my heart, and soul Of all my moral being.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And in thy voice I catch The language of my former heart, and read My former pleasures in the shooting lights Of thy wild eyes. Oh! yet a little while May I behold in thee what I was once, My dear, dear Sister!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And this prayer I make, Knowing that Nature never did betray The heart that loved her; 'tis her privilege, Through all the years of this our life, to lead From joy to joy:", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "For she can so inform The mind that is within us, so impress With quietness and beauty, and so feed With lofty thoughts, that neither evil tongues, Rash judgments, nor the sneers of selfish men, Nor greetings where no kindness is, nor all The dreary intercourse of daily life, Shall e'er prevail against us, or disturb Our cheerful faith that all which we behold Is full of blessings.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Now wilt thou then forget, That after many wanderings, many years Of absence, these steep woods and lofty cliffs, And this green pastoral landscape, were to me More dear, both for themselves, and for thy sake.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A fingering slave, One that would peep and botanize Upon his mother's grave.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A reasoning, self-sufficing thing, An intellectual All-in-all!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "He murmurs near the running brooks A music sweeter than their own.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And you must love him, ere to you He will seem worthy of your love.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The harvest of a quiet eye, That broods and sleeps on his own heart.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Happier of happy though I be, like them I cannot take possession of the sky, Mount with a thoughtless impulse, and wheel there One of a mighty multitude whose way Is a perpetual harmony and dance Magnificent.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Is there not An art, a music, and a stream of words That shalt be life, the acknowledged voice of life?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Not Chaos, not The darkest pit of lowest Erebus, Nor aught of blinder vacancy, scooped out By help of dreams — can breed such fear and awe As fall upon us often when we look Into our Minds, into the Mind of Man.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Sweet Mercy! to the gates of Heaven This minstrel lead, his sins forgiven; The rueful conflict, the heart riven With vain endeavour, And memory of earth's bitter leaven Effaced forever.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And stepping westward seemed to be A kind of heavenly destiny.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I listened, motionless and still; And, as I mounted up the hill, The music in my heart I bore, Long after it was heard no more.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A famous man is Robin Hood, The English ballad-singer's joy.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A Poet worthy of Rob Roy Must scorn a timid song.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Burn all the statutes and their shelves: They stir us up against our kind; And worse, against ourselves.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The good old rule Sufficeth them, the simple plan, That they should take, who have the power, And they should keep who can.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The Eagle, he was lord above, And Rob was lord below.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A brotherhood of venerable trees.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "From Stirling Castle we had seen The mazy Forth unravelled; Had trod the banks of Clyde and Tay, And with the Tweed had travelled; And when we came to Clovenford, Then said \"my winsome marrow,\" \"Whate'er betide, we'll turn aside, And see the braes of Yarrow.\"", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "She was a Phantom of delight When first she gleamed upon my sight; A lovely Apparition, sent To be a moment's ornament;", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A Creature not too bright or good For human nature's daily food; For transient sorrows, simple wiles, Praise, blame, love, kisses, tears and smiles.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And now I see with eye serene The very pulse of the machine.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The reason firm, the temperate will, Endurance, foresight, strength, and skill; A perfect woman, nobly planned, To warn, to comfort, and command.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I wandered lonely as a cloud That floats on high o'er vales and hills, When all at once I saw a crowd, A host, of golden daffodils.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Continuous as the stars that shine And twinkle on the milky way.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Ten thousand saw I at a glance, Tossing their heads in sprightly dance.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A poet could not but be gay, In such a jocund company.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "That inward eye Which is the bliss of solitude.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Stern Daughter of the Voice of God!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "A light to guide, a rod To check the erring, and reprove.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Me this unchartered freedom tires; I feel the weight of chance-desires: My hopes no more must change their name, I long for a repose that ever is the same.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Thou dost preserve the stars from wrong; And the most ancient heavens, through Thee, are fresh and strong.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Give unto me, made lowly wise, The spirit of self-sacrifice; The confidence of reason give, And in the light of truth thy bondman let me live!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Who is the happy Warrior? Who is he That every man in arms should wish to be?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Who, doomed to go in company with Pain, And Fear, and Bloodshed, miserable train! Turns his necessity to glorious gain.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Controls them and subdues, transmutes, bereaves Of their bad influence, and their good receives.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "More skillful in self-knowledge, even more pure, As tempted more; more able to endure, As more exposed to suffering and distress.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But who, if he be called upon to face Some awful moment to which Heaven has joined Great issues, good or bad for human kind, Is happy as a Lover.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And, through the heat of conflict, keeps the law In calmness made, and sees what he foresaw.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Whom neither shape of danger can dismay, Nor thought of tender happiness betray.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "As high as we have mounted in delight, In our dejection do we sink as low.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But how can he expect that others should Build for him, sow for him, and at his call Love him, who for himself will take no heed at all?", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "I thought of Chatterton, the marvellous Boy, The sleepless Soul that perished in his pride; Of Him who walked in glory and in joy Following his plough, along the mountain-side: By our own spirits are we deified: We Poets in our youth begin in gladness; But thereof come in the end despondency and madness.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "That heareth not the loud winds when they call, And moveth all together, if it moves at all.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Choice word and measured phrase, above the reach Of ordinary men.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "And mighty poets in their misery dead.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "For the gods approve The depth, and not the tumult, of the soul.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Mightier far Than strength of nerve or sinew, or the sway Of magic potent over sun and star, Is Love, though oft to agony distrest, And though his favorite seat be feeble woman's breast.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Elysian beauty, melancholy grace, Brought from a pensive though a happy place.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "He spake of love, such love as spirits feel In worlds whose course is equable and pure; No fears to beat away, no strife to heal,— The past unsighed for, and the future sure.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Of all that is most beauteous, imaged there In happier beauty; more pellucid streams, An ampler ether, a diviner air, And fields invested with purpureal gleams.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Yet tears to human suffering are due; And mortal hopes defeated and o'erthrown Are mourned by man, and not by man alone.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Babylon, Learned and wise, hath perished utterly, Nor leaves her speech one word to aid the sigh That would lament her.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Habit rules the unreflecting herd.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "The feather, whence the pen Was shaped that traced the lives of these good men, Dropped from an Angel's wing.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Meek Walton's heavenly memory.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "But who would force the soul tilts with a straw Against a champion cased in adamant.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Give all thou canst; high Heaven rejects the lore Of nicely calculated less or more.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Where music dwells Lingering and wandering on as loth to die, Like thoughts whose very sweetness yieldeth proof That they were born for immortality.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Every gift of noble origin Is breathed upon by Hope’s perpetual breath.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "Oh for a single hour of that Dundee Who on that day the word of onset gave!", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "In years that bring the philosophic mind.", Author = "William Wordsworth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Wordsworth", Text = "To me the meanest flower that blows can give Thoughts that do often lie too deep for tears.", Author = "William Wordsworth" },
        };
    }
}